 async function employeeSaved(){
  if(!personEditor)return;
  const editor=personEditor;let linkError='';
  if(editor.candidate){try{await requestJson('/api/hr/hiring',{action:'linkEmployee',id:editor.candidate.id,version:editor.candidate.version,data:{employeeId:editor.person.id}});}catch(e){linkError='The employee was created, but the candidate link could not be saved. Use Link Existing Employee on the candidate to connect this record. '+(e as Error).message;}}
  await refreshed();
  if(editor.mode==='hire')openPerson(editor.person.id,'Onboarding');
  if(linkError)setError(linkError);
  notify(linkError?'Employee Created · Candidate Link Needs Review':'Employee Record Saved');
 }
