function DepartmentPanel({viewer,onChanged}:{viewer:Viewer;onChanged:()=>Promise<void>}){const [records,setRecords]=useState<FinRecord[]>([]),[error,setError]=useState(''),[loading,setLoading]=useState(true);const load=useCallback(async()=>{try{const data=await requestJson<{records:FinRecord[]}>('/api/people?surface=hr');setRecords(data.records);setError('');}catch(e){setError((e as Error).message);}finally{setLoading(false);}},[]);useEffect(()=>{const timer=setTimeout(()=>void load(),0);return()=>clearTimeout(timer);},[load]);return loading?<p className="hr2-help">Loading Departments…</p>:error?<p className="hr2-error">{error}</p>:<DepartmentSettings records={records} viewer={viewer} onSaved={async()=>{await load();await onChanged();}}/>;}
